// Same rules as the "Code in JavaScript" node in the main RetailGuard workflow.
const suites = $('Split Out Suites').all();
const downloads = $input.all();

function parseCsv(text) {
  const rows = [];
  let row = [], field = '', inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else { inQ = false; }
      } else { field += c; }
    } else if (c === '"') { inQ = true; }
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c === '\r') { /* skip */ }
    else { field += c; }
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  const header = rows.shift() || [];
  return rows
    .filter(r => r.some(v => v !== ''))
    .map(r => {
      const o = {};
      header.forEach((h, idx) => { o[h.trim()] = r[idx] !== undefined ? r[idx] : ''; });
      return o;
    });
}

const num = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const out = [];
downloads.forEach((dl, i) => {
  const suite = suites[i] ? suites[i].json.suite : 'Unknown';
  const records = parseCsv(String(dl.json.csv || ''));
  const seenCaseIds = new Set();

  for (const r of records) {
    const caseId = r['Case ID'];
    const duplicateCaseId = caseId ? seenCaseIds.has(caseId) : false;
    if (caseId) seenCaseIds.add(caseId);

    const opening = num(r['Synthetic Opening Stock']);
    const received = num(r['Synthetic Purchases Received']);
    const customerReturns = num(r['Synthetic Customer Returns Restocked']);
    const sold = num(r['Source Units Sold']);
    const supplierReturns = num(r['Synthetic Supplier Returns']);
    const actualClosing = num(r['Synthetic Actual Closing Stock']);
    const missingStockInputs = [opening, received, customerReturns, sold, supplierReturns, actualClosing].some(v => v === null);

    let expectedClosing = null, variance = null;
    if (!missingStockInputs) {
      expectedClosing = opening + received + customerReturns - sold - supplierReturns;
      variance = actualClosing - expectedClosing;
    }

    const discount = num(r['Source Discount (%)']);
    const inventoryAlert = variance !== null && Math.abs(variance) >= 5;
    const discountAlert = discount !== null && discount >= 20;
    const returnsAlert = customerReturns !== null && customerReturns >= 4;

    const alerts = [];
    if (inventoryAlert) alerts.push('INVENTORY_VARIANCE');
    if (discountAlert) alerts.push('HIGH_DISCOUNT');
    if (returnsAlert) alerts.push('HIGH_CUSTOMER_RETURNS');

    const missingIdentity = !caseId || !r['Date'] || !r['Store ID'] || !r['Product ID'];
    const validationIssues = [];
    if (missingIdentity) validationIssues.push('Missing case/date/store/product identity');
    if (duplicateCaseId) validationIssues.push('Duplicate Case ID');
    if (missingStockInputs) validationIssues.push('Inventory variance unavailable: required stock inputs missing');

    out.push({
      json: {
        suite,
        caseId: caseId || '(blank)',
        input: r,
        result: {
          dataStatus: validationIssues.length ? 'REVIEW_DATA' : 'VALIDATED_FOR_RULES',
          validationIssues: validationIssues.join('; '),
          expectedClosing,
          variance,
          inventoryAlert,
          discountAlert,
          returnsAlert,
          alertTypes: alerts.join(', ')
        }
      }
    });
  }
});

return out;

const flags = (inv, disc, ret) =>
  'inventory=' + inv + ', discount=' + disc + ', returns=' + ret;

return $input.all().map(item => {
  const { suite, caseId, input, result } = item.json;
  const actualFlags = flags(result.inventoryAlert, result.discountAlert, result.returnsAlert);
  const anyAlert = result.inventoryAlert || result.discountAlert || result.returnsAlert;
  let expected = '', actual = '', pass = false;

  if (suite === 'Good') {
    expected = 'No alerts, status VALIDATED_FOR_RULES';
    actual = actualFlags + ', status ' + result.dataStatus;
    pass = !anyAlert && result.dataStatus === 'VALIDATED_FOR_RULES';
  } else if (suite === 'Anomaly') {
    expected = 'At least one alert raised';
    actual = actualFlags;
    pass = anyAlert;
  } else {
    const expStatus = String(input['Data Status'] || '').trim();
    if (expStatus === 'Anomalous Rule Trigger') {
      const expInv = String(input['Inventory Alert'] || '').startsWith('Inventory');
      const expDisc = String(input['Discount Alert (demo rule >=20%)'] || '').startsWith('Discount Alert');
      const expRet = String(input['Returns Alert (synthetic demo rule >=4 units)'] || '').startsWith('Returns Alert');
      expected = flags(expInv, expDisc, expRet);
      actual = actualFlags;
      pass = expInv === result.inventoryAlert && expDisc === result.discountAlert && expRet === result.returnsAlert;
    } else {
      expected = 'Record flagged REVIEW_DATA (expected ' + (expStatus || 'invalid') + ')';
      actual = 'status ' + result.dataStatus + (result.validationIssues ? ' (' + result.validationIssues + ')' : '');
      pass = result.dataStatus === 'REVIEW_DATA';
    }
  }

  return {
    json: {
      'Suite': suite,
      'Case ID': caseId,
      'Expected': expected,
      'Actual': actual,
      'Result': pass ? 'PASS' : 'FAIL',
      'Variance': result.variance,
      'Alert Types': result.alertTypes
    }
  };
});

const rows = $input.all().map(i => i.json);
const bySuite = {};
for (const r of rows) {
  const s = bySuite[r['Suite']] || (bySuite[r['Suite']] = { suite: r['Suite'], total: 0, passed: 0, failed: 0 });
  s.total++;
  if (r['Result'] === 'PASS') s.passed++; else s.failed++;
}
const failed = rows.filter(r => r['Result'] === 'FAIL');
return [{
  json: {
    overallResult: failed.length === 0 ? 'ALL PASSED' : 'FAILURES FOUND',
    totalTests: rows.length,
    passed: rows.length - failed.length,
    failed: failed.length,
    suites: Object.values(bySuite),
    failedCases: failed,
    allResults: rows
  }
}];
